/**
 *  The subscription a browsed repository already has on this machine, so
 *  the page can carry on as that subscription instead of a stranger.
 */
export type SubscriptionRef = {
	scope: Scope,
	source: string,
};

/**  The job an item helps with. */
export type Tag = 
/**  Reading code and saying what is wrong with it. */
"review" | 
/**  Writing, running, or reasoning about tests. */
"testing" | 
/**  Documentation, references, and explaining things in prose. */
"docs" | 
/**  Finding things out — sources, prior art, evidence. */
"research" | 
/**  Deciding what to build and in what order. */
"planning" | 
/**  Reshaping code that already works. */
"refactoring" | 
/**  Working out why something is broken. */
"debugging" | 
/**  Safety, secrets, permissions, and untrusted input. */
"security" | 
/**  Speed, memory, and the cost of running something. */
"performance" | 
/**  Version control — branches, history, worktrees, pull requests. */
"git" | 
/**  Compiling, packaging, versioning, and shipping a release. */
"release" | 
/**  Databases, schemas, migrations, and analysis. */
"data" | 
/**  Interfaces: layout, styling, design systems, accessibility. */
"ui" | 
/**  Talking to other services — APIs, webhooks, third-party tools. */
"integration" | 
/**  Driving other tools and agents, and the workflows that chain them. */
"automation";

/**  A defect at a place in the template, with what to do about it. */
export type TemplateFinding = {
	/**  1-based line; 0 where the whole file is the subject. */
	line: number,
	problem: string,
	fix: string,
};

/**
 *  A scope whose standing could not be read at all, and why. The reason
 *  travels with it so the Updates note naming the place says the cause
 *  without a second read. Only the message travels — no typed kind — and
 *  the Problems page is where a cause is told apart from its neighbour.
 */
export type UnreadableScope = {
	scope: Scope,
	message: string,
};

/**
 *  What unsubscribing from a marketplace would do: the packages that can be
 *  removed or kept as-is, the ones the user edited (which must be forked or
 *  discarded first), and the curated sets that leave with the source.
 */
export type UnsubscribePreview = {
	removable: PackageRef[],
	edited: PackageRef[],
	bundles: string[],
};

/**
 *  What unsubscribing did about the repository effects of the packages
 *  that left with the source — the same account the terminal prints.
 * 
 *  A struct rather than the bare list it used to be, spelling the account
 *  `undone` like every other command that can make one. The window reads
 *  the account off an answer by that name, so a bare list is a shape it
 *  can only be told about by hand, and the day this write goes through
 *  the shared one it would fall silent with nothing going red.
 */
export type Unsubscribed = Unsubscribed_Serialize | Unsubscribed_Deserialize;

/**
 *  What unsubscribing did about the repository effects of the packages
 *  that left with the source — the same account the terminal prints.
 * 
 *  A struct rather than the bare list it used to be, spelling the account
 *  `undone` like every other command that can make one. The window reads
 *  the account off an answer by that name, so a bare list is a shape it
 *  can only be told about by hand, and the day this write goes through
 *  the shared one it would fall silent with nothing going red.
 */
export type Unsubscribed_Deserialize = {
	undone: string[],
};

/**
 *  What unsubscribing did about the repository effects of the packages
 *  that left with the source — the same account the terminal prints.
 * 
 *  A struct rather than the bare list it used to be, spelling the account
 *  `undone` like every other command that can make one. The window reads
 *  the account off an answer by that name, so a bare list is a shape it
 *  can only be told about by hand, and the day this write goes through
 *  the shared one it would fall silent with nothing going red.
 */
export type Unsubscribed_Serialize = {
	undone?: string[],
};

/**  One declared package's update standing. */
export type UpdateRow = {
	scope: Scope,
	kind: ItemKind,
	name: string,
	source: string,
	repo: string,
	/**
	 *  `repo` as [`crate::source_ref::repo_identity`] spells it — the one
	 *  identity two scopes' rows share when they name one repository two
	 *  ways, on any host.
	 */
	repoIdentity: string,
	/**  The content revision installed now, when the lock records it. */
	current: VersionRef | null,
	/**  The newest content revision the mirror knows. */
	latest: VersionRef | null,
	/**
	 *  The package's files changed between current and latest — a moved
	 *  repository that never touched this package is not an update.
	 */
	updateAvailable: boolean,
	/**
	 *  Held at a version — the effective installation graph's word, not
	 *  only the item's own `rev`: a pinned source, a pinned bundle, or a
	 *  pinned dependency parent all hold what they carry.
	 */
	pinned: boolean,
	/**  Who holds it, when `pinned`. */
	holdOwner: HoldOwner | null,
	/**  The user asked to stop hearing about this package's updates. */
	ignored: boolean,
	/**
	 *  The installed files were edited by hand; updating is blocked until
	 *  the edit is kept as a fork or discarded.
	 */
	blockedByLocalEdit: boolean,
	/**
	 *  Which renderings carry the edit, one entry per physical rendering:
	 *  an agent renders once per tool, while tools sharing a skill's
	 *  canonical tree count once. Keeping the edit as a fork captures one
	 *  rendering's bytes — it has to be the one that was changed.
	 */
	editedHarnesses: HarnessId[],
	/**  The edited rendering the engine allows the UI to capture, when one exists. */
	forkableHarness: HarnessId | null,
	/**
	 *  Whether dropping the edits can put the currently resolved content
	 *  back in place, without moving any revision — the source content
	 *  resolved, whether or not its history could be read. False once the
	 *  source no longer carries the package.
	 */
	canDiscard: boolean,
	/**
	 *  Whether this place can move to the newest content on its own: the
	 *  newest is known, and the hold — if any — is this declaration's to
	 *  move rather than a bundle's or parent's.
	 */
	canTakeLatest: boolean,
	/**
	 *  Installed as a bundle member or a dependency, with no declaration
	 *  of its own: whatever pulled it in owns its revision, and a fork
	 *  needs a declaration to turn local.
	 */
	derived: boolean,
	/**
	 *  Every installed package that requires this one, when that is why it
	 *  is here — the names behind `derived`, so the Library can say who
	 *  brought it rather than that something did. Empty for a package
	 *  declared outright and for a bundle member, whose set is named where
	 *  sets are. All of them, never one: releasing the only package named
	 *  would leave it installed for the rest.
	 */
	requiredBy: string[],
	/**  This package is a local fork of a catalog item. */
	forked: boolean,
	/**  Installations of this package disagree on their source commit. */
	mixed: boolean,
	/**  The source's tracked tip no longer carries this package at all. */
	removedUpstream: boolean,
	/**
	 *  Why this place is never updated one package at a time, when it is
	 *  not: the planner derives no plan for the kind, so an Update offered
	 *  here could only be refused. `None` for every kind that does plan.
	 * 
	 *  The refusal travels with the row rather than being worked out again
	 *  where it is shown: a surface deciding for itself which kinds are
	 *  refused is a second account of a rule that lives in
	 *  [`crate::engine::plans_per_package`].
	 */
	noPerPackageUpdate: string | null,
};

/**
 *  One package a batched update names, and where its hold goes.
 * 
 *  `hold` is the commit a held place's Update moves its hold to. A
 *  following place carries `None`, which leaves its declaration exactly as
 *  it is — never confused with the `None` [`super::set_rev`] takes to mean "stop
 *  holding this", because that instruction is not one an Update ever
 *  gives.
 */
export type UpdateTarget = {
	kind: ItemKind,
	name: string,
	hold: string | null,
};

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport = UpdatesReport_Serialize | UpdatesReport_Deserialize;

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport_Deserialize = {
	rows: UpdateRow[],
	warnings: ItemWarning_Deserialize[],
	/**
	 *  Scopes whose standing could not be read at all — a lock or manifest
	 *  this build refuses. Carried as data, like [`crate::engine::ItemWarning`]
	 *  above and for the same reason: one place's unreadable record must
	 *  not blank every other place's standing. Always empty from
	 *  [`updates`], which answers for one scope and fails outright; the
	 *  multi-scope caller folding those answers together fills it.
	 */
	unreadable: UnreadableScope[],
	/**
	 *  When the mirrors behind this standing were last brought current —
	 *  Unix seconds, `None` when nothing has ever fetched. A clean report
	 *  is only as true as the fetch under it, so the age of that fetch
	 *  travels with it rather than being left for the reader to guess.
	 * 
	 *  `u32` for the same reason [`crate::model::ObservedItem::modified_at`]
	 *  is: specta refuses to export a 64-bit int across the IPC boundary.
	 */
	lastFetched: number | null,
};

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport_Serialize = {
	rows: UpdateRow[],
	warnings: ItemWarning_Serialize[],
	/**
	 *  Scopes whose standing could not be read at all — a lock or manifest
	 *  this build refuses. Carried as data, like [`crate::engine::ItemWarning`]
	 *  above and for the same reason: one place's unreadable record must
	 *  not blank every other place's standing. Always empty from
	 *  [`updates`], which answers for one scope and fails outright; the
	 *  multi-scope caller folding those answers together fills it.
	 */
	unreadable: UnreadableScope[],
	/**
	 *  When the mirrors behind this standing were last brought current —
	 *  Unix seconds, `None` when nothing has ever fetched. A clean report
	 *  is only as true as the fetch under it, so the age of that fetch
	 *  travels with it rather than being left for the reader to guess.
	 * 
	 *  `u32` for the same reason [`crate::model::ObservedItem::modified_at`]
	 *  is: specta refuses to export a 64-bit int across the IPC boundary.
	 */
	lastFetched: number | null,
};

/**  One version a row points at. */
export type VersionRef = {
	commit: string,
	/**  Release name when a tag points at the commit. */
	label: string | null,
	date: string | null,
};

/**
 *  One version of a package: a commit that changed its files, wearing any
 *  tag names that point at it.
 */
export type VersionRow = {
	/**  Full commit id. */
	id: string,
	/**  The release name, when a tag points at this commit. */
	label: string | null,
	/**  ISO-8601 committer date. */
	date: string,
	summary: string,
	/**  This is the content revision the installed package holds. */
	installed: boolean,
	newerThanInstalled: boolean,
};

/**  One side of the comparison. */
export type VersionSel = 
/**  The package's source subtree at a commit. */
{ at: "commit"; commit: string } | 
/**  What is installed on disk right now. */
{ at: "installed" };

/**  An effect that was neither shown nor offered, and why. */
export type Withheld = {
	/**  Display text: shown once, printed as it is. */
	name: string,
	reason: string,
};

/**
 *  Why a whole-file write did not happen. Refusing is a normal answer
 *  here, not a failure, so it is a shape the page can act on rather than
 *  a message it would have to recognise by its words.
 */
export type WriteRefused = 
/**
 *  The file is no longer the one this copy was read from, and the
 *  refusal carries no account with it. Something else wrote the file
 *  — a fork, a hold, an install, another window — and writing this
 *  copy would put that back, so reading the file again is the whole
 *  of the way out.
 */
{ kind: "stale" } | 
/**
 *  Anything else that stopped the write, in the words the person
 *  gets — a stale file among them, where the write had something to
 *  say about the packages leaving before it refused and a bare reload
 *  would drop it.
 */
{ kind: "failed"; message: string };

/**  One path the package writes, where it actually lands. */
export type Written = {
	/**
	 *  Absolute, because the whole value of the line is that a reader can
	 *  go and look. Display text: shown once, printed as it is.
	 */
	path: string,
	/**
	 *  Inside the repository's common git directory, which every work tree
	 *  of the repository shares — so this file is the repository's, not
	 *  this checkout's.
	 */
	shared: boolean,
};

export type ZoomState = {
	/**
	 *  The size on screen. Every resize the window takes moves it, so a
	 *  page that has just reloaded reads what it is looking at.
	 */
	percent: number,
	/**
	 *  The window would not take the saved size when it opened, so
	 *  `percent` is the fallback and the saved size is not on screen. A
	 *  fact about the opening: a resize that works later moves the size but
	 *  does not make the opening have worked.
	 */
	launchRefused: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

